namespace ghidra.feature.vt.gui.actions;





using docking;
using docking.action;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.provider.markuptable;
using ghidra.feature.vt.gui.provider.matchtable;
using ghidra.feature.vt.gui.task;
using ghidra.util;

public class ApplyMatchAction : DockingAction {

	public static readonly string NAME = "Apply Markup";
	private static readonly string MENU_GROUP = VTPlugin.EDIT_MENU_GROUP;

	private VTController controller;

	public ApplyMatchAction(VTController controller) : base(NAME, VTPlugin.OWNER)
    {
		this.controller = controller;

		Icon icon = MarkupStatusIcons.APPLIED_ICON;
		setToolBarData(new ToolBarData(icon, MENU_GROUP));
		setPopupMenuData(new MenuData(new string[] { NAME }, icon, MENU_GROUP));
		setEnabled(false);
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Apply_Markup"));

	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		VTMatchContext matchContext = (VTMatchContext) context;
		List<VTMatch> matches = matchContext.getSelectedMatches();

		ApplyMatchTask task = new ApplyMatchTask(controller, matches);
		controller.runVTTask(task);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is VTMatchContext)) {
			return false;
		}
		VTMatchContext matchContext = (VTMatchContext) context;
		List<VTMatch> matches = matchContext.getSelectedMatches();
		if (matches.size() == 0) {
			return false;
		}

		return true;
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		return true;
	}
}
